_ICON_CACHE = {}

def get_svg_icon(name: str, color: str = "#cbd5e1", size: int = 16) -> QIcon:
    """
    Renders an SVG template into a crisp QIcon with the specified color and size.
    Caches the generated QIcon for instant subsequent lookups.
    """
    cache_key = (name, color, size)
    if cache_key in _ICON_CACHE:
        return _ICON_CACHE[cache_key]

    template = _SVG_TEMPLATES.get(name)
    if not template:
        return QIcon()

    colored_svg = template.replace('currentColor', color)
    svg_bytes = QByteArray(colored_svg.encode('utf-8'))
    
    renderer = QSvgRenderer(svg_bytes)
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)
    
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()

    icon = QIcon(pixmap)
    _ICON_CACHE[cache_key] = icon
    return icon

def get_svg_pixmap(name: str, color: str = "#cbd5e1", size: int = 16) -> QPixmap:
    """Returns a QPixmap directly for painting on custom widgets."""
    template = _SVG_TEMPLATES.get(name)
    if not template:
        return QPixmap()

    colored_svg = template.replace('currentColor', color)
    svg_bytes = QByteArray(colored_svg.encode('utf-8'))
    
    renderer = QSvgRenderer(svg_bytes)
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)
    
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()
    return pixmap
